      "description": "每個城市都會有至少一條美麗的河流，也是深入城市走讀生態人文學習的好場域。本學期課程將藉由引領學員認識新店溪流域、雙北美好水岸及桃竹友美好水城環境走讀！ \n帶領學員進行新店溪流域主、支流生態、人文走讀與主題學習，發展新店區溪流定點拍照、記錄與親水活動解說路線的資源盤點；課程期間也會安排跨北台城市的流域走讀學習、觀摩，期望引領更多學員從關心城市溪流環境行動，共同推進台北成為水城好家園。",
