      "name": "實用珠寶玉石學(萬華國中校區)",
      "description": "本課程以「寶石學基礎」為核心，結合「實務鑑定」與「市場判讀」，透過系統化教學，引導學員從日常常見寶石入門，逐步建立礦物特性、光學現象與鑑別邏輯之整體認知。 \n \n課程設計採由淺入深之架構，先建立基礎觀察能力，再進入多種寶石之比較分析與實物判讀，並透過案例導入與市場解析，使學員理解寶石之價值形成因素（如顏色、透明度、處理方式與市場供需）。 \n \n同時強調「實物操作」與「觀察訓練」，培養學員以科學方法進行判斷，而非僅依外觀或價格做決策，進一步建立理性選購與基礎鑑定能力。",
