      "description": "經過龍韻口琴A班四冊的學習後對複音口琴獨奏已經有很好的基礎建立，獨奏B班的課程將會對複音口琴獨奏技巧做更深入的應用與探討；此外，本班還會對【半音階口琴】做基礎的教學，歡迎對半音階口琴有興趣的學員報名參加。 \n \n『龍韻口琴班』特色： \n★依個人程度分組授課，不必擔心個人能力是否能跟上全體。 \n★學習目標明確，依階段循序漸進的晉級；成就感滿滿。 \n★班級氣氛融洽，學員如好友／家人般互相關懷。 \n★口琴班朝長期且多元方式經營；除基礎班的開設外還有樂團合奏班、複音獨奏進階演奏班以及半音階口琴基礎課程可參與。",
