      "name": "法國香頌學法語：唱歌也能開口說",
      "description": "法語歌曲不管是經典香頌、音樂劇或是現代流行歌曲，都令人回味無窮。 \n唱得出一首法語歌，自娛娛人、陶冶性情，為生活增添一份浪漫風情。 \n \n想像走在巴黎的小街，咖啡館傳來一首老歌，你忽然聽懂了一句法語。 \n那一刻，世界也同時向你打開。 \n這門課，我們用法國最動人的香頌，學會最自然的法語。 \n一起唱著經典與現代歌曲，在旋律裡學會： \n \n✔ 最實用的法語句子 \n✔ 自然開口的發音節奏 \n✔ 歌曲背後的法國文化 \n \n不需要音樂基礎，也不需要會法語。 \n只要喜歡法國、喜歡歌曲，就能一起唱、一起說。 \n \n在歌聲裡，慢慢把法語說出來。",
      "teacher": "陳慧萍",
      "experience": "現職：英語&法語教師，經歷：● 2025-07-01~2026-03-06 台北市信義社區大學 法語講師 台北市 自編講義與法語授課>> \n● 2025-02-06~2026-03-06 台北市文山社區大學 法語講師 台北市 自編講義與法語授課>> \n● 2012-10-12~2025-06-30 意妍堂製作 影視編審 台北市 國內主要紀錄片頻道節目中英法翻譯審核，如「Discovery/動物星球/旅遊生活頻道」和「國家地理頻道」。>> \n● 2004-09-01~2012-06-10 翰林出版社 特約編輯 台北市 英語教學延伸教材編輯",
