      "description": "1. 技能學習與創作發展： \n鉤針編織是一門結合技術與藝術的手工藝，在學習基本技巧的同時，也能發揮創造力與審美感。透過鉤織娃娃和配件，學員不僅能掌握鉤針技巧，還能自由設計與創作，體驗從無到有的成就感。 \n \n2. 心靈療癒與專注力培養： \n鉤織是一種需要專注的手作活動，能幫助學員在繁忙的生活中找到一段寧靜的時光，放慢步調，紓解壓力。重複的編織動作如同冥想，能提升專注力與耐心，達到心靈療癒的效果。 \n \n3. 成就感與自信心的提升： \n完成一件作品的過程，能讓學員從學習、實作到完成的每個階段，感受到努力的成果。這不僅帶來滿滿的成就感，也能提升自信，讓學員相信自己有能力創造美好的事物。 \n \n4. 連結與分享的溫度： \n鉤織娃娃不僅是個人的創作，也可以成為分享愛與溫暖的方式。手工製作的玩偶能成為獨特的禮物，傳遞心意，甚至與家人朋友一起編織，促進人際交流，讓手作變成美好的生活體驗。",
      "teacher": "黃心怡",
      "experience": "現職：，經歷：● 2023-02-18~2024-09-25 家福公益編織社 社團指導老師 家樂福總公司 設計課程內容，鉤針基礎編織教學，包包編織，草帽編織以及鉤針娃娃編織教學等。>> \n● 2018-10-01~2024-09-25 黛娜手作樂園 公益團鉤娃娃設計以及公益團鉤主辦 大台北地區 設計公益娃娃，並且每年二次（耶誕節和兒童節）舉辦大型團鉤活動招募有志者一起來鉤織娃娃，再把作品送去全台各大醫院兒童病房及兒癌病房陪伴孩子們。>>",
