      "name": "手作美學–金工、青花與多媒材",
      "description": "本學期我們將學習目標放在多媒材與金工琺瑯學習及設計、自製白瓷胎體,學習技巧並得以小量生產, 藉以創新元素及對抗通膨,本期邀請大家以一個設計師的視角創作商品概念為主軸,提高產學作品的細緻與深度。 \n \n金屬工藝在生活種佔據著各種重要的實用價值與生活創意, 在社大金工手作的課程中,認識常用金屬學習技巧,與實用的創作. \n響應政府的環境永續政策推動, 檢視在金屬加熱過程如何降低耗能與節能方法,設計友善環境與落實綠色 \n金工, 金工為基礎，搭配白瓷與多媒材呈現創作的多視角趣味與學習，讓作品呈現更多樣的視覺表情,享受一趟美好的工藝之旅. \n \n本課程適合想要探索金工表現、色彩與技法精進的朋友一起加入 !!",
