      "id": "1152C4006",
      "seq": 129,
      "name": "魔幻電吹管",
      "description": "電吹管，用吹的電子琴！內建多種極富表現力的樂器音色，不只是電子薩克斯風，他還可以是小號，二胡，提琴，笛簫，蘇格蘭風笛........... 一管多用，輕巧多工，方便練習又不擾鄰，實現了使用吹奏的方式來演奏電子樂器，同時支援立即轉調，像電子琴一樣按個鍵就可以完成轉調，攜帶方便又容易學習，非常適合長青族群。 \n電吹管內鍵60多種音色，人手一支電吹管樂器，卻可以吹奏出不同中西(樂器)音色，宛如一個小型交響樂團，以富創意的表演及充滿熱忱的演奏，培育新一代音樂文化，帶來情感的共鳴、使人變得更積極有活力。",
