      "seq": 132,
      "name": "達人爵士鼓（進階）",
      "description": "本課程為成年學員打造輕鬆愉快的學習環境，讓退休人士、音樂愛好者或想重拾興趣的成年人，透過爵士鼓享受音樂的樂趣與活力。課程以「實用性」與「趣味性」為核心，注重個人需求與學習節奏，從基礎節奏訓練到經典曲目演奏，逐步建立學員信心。融入多元風格如爵士、搖滾、流行，豐富音樂視野。透過團體合奏與成果發表，促進學員互動與社區連結，讓音樂成為放鬆身心、提升生活品質的方式。無論初學者或略有基礎，這裡都是充滿支持與鼓勵的學習天地，讓音樂成為生活中的快樂源泉。",
