      "name": "生活與手機攝影美學",
      "description": "生活中，利用相機、手機為自己、親朋好友留下美好回憶，或紀錄在地文化、自然環境、國內外旅遊的點點滴滴。「生活與手機攝影美學」將引導同學對人與人、人與環境之間關係，作相對全面的、誠實生動的描寫，並培養同學發揮藝術創意，充實精神生活及美化生命內涵。",
