      "name": "花鳥相伴輕旅行(室內課程為下午)",
      "description": "本課程以「城市生態學」為核心視野，將萬華視作生物遷徙與棲息的重要廊道。課程設計由室內基礎理論延伸至戶外實地調查，聚焦於「青年公園」的都會綠肺生態及「華江雁鴨自然公園」這座「艋舺綠寶石」的濕地系統。透過深度導引與生態解說，引領學員從微觀的鳥類行為觀察，宏觀至探討都市開發與生物多樣性共存的價值，實踐人與自然和諧共生的在地環境倫理。",
