      "bio": "現職：畢業於台科大建築系，從高中到研究所皆投入學習建築，也在建築產業與文化資產調查工作中累積了豐富經驗。近年專注於自然美學與參與式設計，以及美學教育與野地課程，擁有多項野外專業認證（WFR、LNT、TWEA）。帶領不同年齡層的學員一起走入不同場域、觀察細節、感受空間與人的互動，更進一步實行空間微型改造。個人創作橫跨原民文化、山林地圖與圖像敘事，持續探索土地與生命的變化軌跡。，經歷：● 2020-06-01~2021-01-31 新北市汗得建築工事實驗教育機構 業師 北市青年公園太陽圖書館二樓 「建築製圖、建築社會人、建築測繪」授課業師>> ● 2020-11-01~2021-01-19 國語實小公共藝術設置計畫 外聘講師 北市國語實小 《打開圍牆，從走廊到操場》實驗工作坊講師>> ● 2021-08-02~2021-09-09 桃園市少年輔導委員會 外聘講師 憲光二村 外展活動—彩繪課課程講師>>",
