      "source_folder": "1150729 已PO 花藝",
      "course": "花藝人才養成班",
      "course_id": "1152C3017",
      "teacher": "林淑媛",
      "title": "「花」現新生活，美好在「藝」起，走進花的世界，開啟新的視野",
      "excerpt": "。 我參加社區大學的花藝人才養成班己邁入第三年，由林淑媛老師代領大家走進花的世界，這是我每週最期待的課程。 每日在工作忙碌的泥流中，每當壓力大到喘不過氣時，每週六的花藝課是我的身心靈充電站，在淑媛老師專業細心教導下，從無到有的插花技能逐漸提昇，「有夢最美，逐夢踏實」，老師總是優雅地指導我們精進技能，這是一堂極具療癒紓壓與作品賞心悅目的超值課程，也納入了我的退…",
      "full_text": "115-1_花藝人才養成班_林淑媛老師_學員楊珊珊 標題:「花」現新生活，美好在「藝」起，走進花的世界，開啟新的視野。 我參加社區大學的花藝人才養成班己邁入第三年，由林淑媛老師代領大家走進花的世界，這是我每週最期待的課程。 每日在工作忙碌的泥流中，每當壓力大到喘不過氣時，每週六的花藝課是我的身心靈充電站，在淑媛老師專業細心教導下，從無到有的插花技能逐漸提昇，「有夢最美，逐夢踏實」，老師總是優雅地指導我們精進技能，這是一堂極具療癒紓壓與作品賞心悅目的超值課程，也納入了我的退休計劃首選課程。 走進課堂中的五感體驗，讓人忘卻煩憂，走進美好的心流狀態，每一次插花都是成長的累積，我有時因精神不濟在插花造型不是很完整時，老師總會耐心鼓勵指導，並給予一對一示範教學，提昇學員信心與學習的正能量。",
