      "title": "日本藍染文化與基礎技法｜115-1 學員學習心得",
      "excerpt": "藍染課不只是學習一項傳統工藝，更像走進一個充滿歡笑與溫暖的大家庭。在美湘老師細心又耐心的帶領下，即使是沒有任何基礎的初學者，也能一步一步享受藍染創作的樂趣。 從構圖設計、縫製、綁紮、防染，到下染缸、玩漸層，每一道工序都充滿期待與驚喜。同學們一邊學習、一邊交流，彼此分享技巧、互相欣賞作品，教室裡總是充滿笑聲與成就感。最令人期待的，就是打開作品的那一刻，每個人都…",
      "full_text": "藍染課不只是學習一項傳統工藝，更像走進一個充滿歡笑與溫暖的大家庭。在美湘老師細心又耐心的帶領下，即使是沒有任何基礎的初學者，也能一步一步享受藍染創作的樂趣。 從構圖設計、縫製、綁紮、防染，到下染缸、玩漸層，每一道工序都充滿期待與驚喜。同學們一邊學習、一邊交流，彼此分享技巧、互相欣賞作品，教室裡總是充滿笑聲與成就感。最令人期待的，就是打開作品的那一刻，每個人都會因為藍染獨一無二的紋樣而驚艷，也常引來同學們此起彼落的讚嘆聲。 在這裡，不只是學會藍染技法，更收穫了創作的喜悅、朋友間的情誼，以及放鬆身心的美好時光。這麼有趣、療癒又充滿成就感的課程，真的值得親自來體驗。 如果您也想為生活增添一抹專屬自己的藍色，歡迎加入我們，一起感受藍染藝術的魅力！ 藍染班長 胡湘薇",
