      "course_id": "1152C4022",
      "teacher": "張宇樞",
      "title": "龍韻口琴獨奏B班｜115-1 學員學習心得",
      "excerpt": "龍韻口琴115春季獨奏B班學員心得報告 上課時間：週四(晚) ◆學員【陳心怡】上課心得： 半音階口琴和複音口琴最大的不同，在於一個孔位包含四個音，因此在吹奏時，必須對音的位置有非常清楚的概念。除了要熟悉孔位配置，還需要透過反覆練習，讓手、口和大腦之間建立流暢的連結。 剛開始學習時，常常會因為不夠熟悉而吹錯孔位，甚至在曲子進行中「迷路」，一不小心就找不到自己吹…",
      "full_text": "龍韻口琴115春季獨奏B班學員心得報告 上課時間：週四(晚) ◆學員【陳心怡】上課心得： 半音階口琴和複音口琴最大的不同，在於一個孔位包含四個音，因此在吹奏時，必須對音的位置有非常清楚的概念。除了要熟悉孔位配置，還需要透過反覆練習，讓手、口和大腦之間建立流暢的連結。 剛開始學習時，常常會因為不夠熟悉而吹錯孔位，甚至在曲子進行中「迷路」，一不小心就找不到自己吹到哪裡。但也正因如此，更能體會半音階口琴的挑戰性與魅力。每當能夠順利完成一首曲子時，都會有很大的成就感，也讓人更有動力繼續練習。 ◆學員【高珮珊】上課心得： 今年第一次來上社大的課，感覺很新鮮也很好玩。 記得第一次到社大上口琴課的那天，我本來想請假，因為有點害怕新環境和新同學，問我為何害怕？我也說不上來，不過擔心終究是多於，同學人都超好。 老師細心教學，上課會從呼吸法開始練習，雖我學口琴已快二十年，但這是我第一次留意到吹口琴需要這麼在意「呼吸」這件事。 一些兒歌也讓我彷彿回到小時候，剛學習唱歌的那時候。比如火車快飛、孤挺花等等。 希望下學期能學到更多口琴曲。",
