      "teacher": "程錦玲",
      "title": "鼓動生命和太鼓｜115-1 學員學習心得",
      "excerpt": "學員學習心得 (Ｆ 類_精緻文化與生活品味) 期別：1151 期 課程名稱：鼓動生命和太鼓 課程編號010：F221A 上課時間：每週四 晚上 教師：程錦玲 老師 學員：【王正綱】： 跟著錦玲老師學打太鼓進入第10學期，不再是隨意得敲敲打打、活動筋骨。 開始瞭解擊鼓的節奏要保持一致，最須要練習的就是基本功。也逐漸要求個人在站姿、鼓棒握法、擊鼓要領，以及如何手…",
      "full_text": "學員學習心得 (Ｆ 類_精緻文化與生活品味) 期別：1151 期 課程名稱：鼓動生命和太鼓 課程編號010：F221A 上課時間：每週四 晚上 教師：程錦玲 老師 學員：【王正綱】： 跟著錦玲老師學打太鼓進入第10學期，不再是隨意得敲敲打打、活動筋骨。 開始瞭解擊鼓的節奏要保持一致，最須要練習的就是基本功。也逐漸要求個人在站姿、鼓棒握法、擊鼓要領，以及如何手腦協調，讓鼓棒落下的時間點滿足節拍音符。 時時提醒自己避免出現下面的幾個狀況： 兩腳掌沒有站在鼓的兩側，讓身軀保持在鼓的中心 雙腳膝蓋未微微彎曲 左腳掌離鼓太遠；彎曲左膝蓋時，鼓棒應該可以敲打到鼓邊 身軀前傾或彎腰駝背 手指用力地緊握鼓棒，而非以姆指和食指夾住+其他三指微握鼓棒 把姆指壓在鼓棒上面 鼓棒沒有與手臂保持直線 右腳掌距離左腳掌太近；兩隻手臂自然放下時，鼓棒應在鼓面的中心略高處 擊鼓時，沒有保持鼓棒在鼓面直上直下 擊鼓時，壓住鼓棒，使其停留在鼓面太久，而不是馬上彈起 高舉鼓棒時，無法筆直向上 打太鼓不再是蠻力的揮棒；讓大腦流暢地跳出曲目的鼓譜音符，帶動起全身韻律的節奏，雙手的鼓棒輕鬆地上下飛舞。進入這樣的境界，太鼓會讓你我的身、心、靈融合一體。",
