      "id": "story-13",
      "semester": "115-1 春季",
      "source_folder": "1150803 以PO 咖啡",
      "course": "喝懂咖啡風味",
      "course_id": "1152C9002",
      "teacher": "楊焌賢",
      "title": "原來，咖啡真的喝得懂",
      "excerpt": "原來，咖啡真的喝得懂 以前的我，其實對咖啡沒有太多研究。平常就是喝咖啡，知道有深焙、中焙、淺焙，但如果要我說出它們的差別，或是哪個產區有什麼特色，我大概都回答不出來，更不用說什麼水溫、研磨粗細、沖煮時間這些細節。 有一次去萬華社大的成果展逛逛，剛好看到新開了一門「喝懂咖啡風味」的課（楊焌賢老師）。當時也沒有想很多，只覺得好像很有趣，就衝動報名了。 開始上課之…",
      "full_text": "原來，咖啡真的喝得懂 以前的我，其實對咖啡沒有太多研究。平常就是喝咖啡，知道有深焙、中焙、淺焙，但如果要我說出它們的差別，或是哪個產區有什麼特色，我大概都回答不出來，更不用說什麼水溫、研磨粗細、沖煮時間這些細節。 有一次去萬華社大的成果展逛逛，剛好看到新開了一門「喝懂咖啡風味」的課（楊焌賢老師）。當時也沒有想很多，只覺得好像很有趣，就衝動報名了。 開始上課之後才發現，原來一杯咖啡可以有這麼多變化。楊老師每堂課都會現場沖煮不同的咖啡，也會故意改變不同的條件，例如水溫高一點、低一點，研磨粗一點、細一點，或是換不同的濾杯、濾紙，甚至改變注水方式和沖煮時間。明明是同一支咖啡豆，喝起來卻完全不一樣。 以前喝咖啡，大概只有「好喝」跟「不好喝」的差別。現在慢慢開始會去注意，原來有些咖啡帶著水果香，有些比較像堅果、巧克力，有些酸甜很舒服，有些尾韻會回甘。雖然很多風味我還喝不太出來，但至少開始知道老師在說的是什麼。老師上課分享的內容很多，有些是多年累積下來的經驗。我常常覺得自己沒有辦法一次全部吸收，下課回家過幾天，好像又忘了一些。不過每個星期還是很期待上課，也很期待老師今天又會帶什麼咖啡來跟大家分享。 學期快結束的時候，我也開始自己買咖啡豆、買器材，在家慢慢練習手沖。說真的，到現在我還沖不出老師示範時那麼豐富、那麼乾淨的風味。有時候明明覺得是照著老師的方法做，喝起來還是不太一樣。不過，每次只要調整一點水溫、磨豆粗細，或是注水方式，再喝到不同的味道，就覺得很有趣。 在報名下一期課程時，我其實也想過：「我又沒有要開咖啡店，真的還要繼續上嗎？」後來想想，好像不是這樣。我想學咖啡，不是為了考證照，也不是要成為咖啡師，而是希望有一天，可以在家裡，沖出一杯自己真正喜歡喝的咖啡。更重要的是，這堂課讓我認真看待沖煮一杯好咖啡真的不容易，也認識了許多以前從來沒有接觸過的精品咖啡風味。 原來，咖啡真的喝得懂。而且，越喝越覺得有意思。所以，我又報名了下一期。",
