      "id": "story-16",
      "semester": "115-1 春季",
      "source_folder": "1150804 已PO龍韻口琴A班",
      "course": "龍韻口琴獨奏A班",
      "course_id": "1152B2006",
      "teacher": "張宇樞",
      "title": "龍韻口琴獨奏A班｜115-1 學員學習心得",
      "excerpt": "龍韻口琴115春季獨奏A班學員心得報告 上課時間：週三(晚) ★學員【黃美滿】 上課心得： 老師、學長姐、同學大家好 我是A班同學黃美滿，我喜歡口琴的聲音，但一直沒機會和因緣學習口琴，有一天和高中同學聚會（淑君班長），她說，她在社大上口琴班，我二話不說，直接請她幫我報名，她說已經上了三週了要回去問老師；得到的消息是老師說上下一期，我說沒關係，妳先幫我買口琴，…",
      "full_text": "龍韻口琴115春季獨奏A班學員心得報告 上課時間：週三(晚) ★學員【黃美滿】 上課心得： 老師、學長姐、同學大家好 我是A班同學黃美滿，我喜歡口琴的聲音，但一直沒機會和因緣學習口琴，有一天和高中同學聚會（淑君班長），她說，她在社大上口琴班，我二話不說，直接請她幫我報名，她說已經上了三週了要回去問老師；得到的消息是老師說上下一期，我說沒關係，妳先幫我買口琴，所以，我先買了口琴等了一學期，終於開學了！ 我的等待是值得的~ 雖然班上有四本教材不同級別，但是，老師教學經驗豐富，很有系統的把四個級別融入一個班級，讓同學安心的跟著進度學習，沒有焦慮和違和感，這就是老師的功力了。 我喜歡班上的氛圍，大家來自不同的領域職場，但是，到上課時間，就是一起學習的同學互相照顧! 謝謝老師耐心教授 謝謝學長姐貼心提點 謝謝同期同學做伴學習 謝謝社大有口琴班 因為有如此美好的因緣，豐富了花甲之年的老靈魂，感恩。 ★學員【李培毅】 上課心得： 報名學習口琴只是想娛樂自己並消磨時間，因為樂譜對我而言如無字天書，沒想到上課三個月，經老師細心講解，竟然大有斬獲，這學期感覺收獲頗豐，選對了老師，上課是件快樂的事。 ★學員【胡秋香】 上課心得： 我是口琴A班胡秋香，之前雖然曾斷斷續續上過一點口琴課，但一曝十寒課程並未持續，自我學習也成效不佳。 去年底發憤圖强想要重新開始，就在網路上努力搜尋，終於發現萬華社大有我心目中規劃最完善的口琴教學課程，所以不遠千里(只有10幾公里)而來拜師學藝。 張老師自編的教材內容新穎豐富，學生分四個級別却又同班上課，個人可依需求或新學或預習或複習，循序漸進逐步提昇程度，就我而言，本學期受益良多！ 張老師教學態度認真嚴謹，對年長的學生却又體貼入微，實在是口琴界不可多得的良師，能夠受教於張老師是我的榮幸！ ★學員【徐大潼】 上課心得： 在上張老師課之前，我自己有上網摸索自學了一段時間，但苦於碰到瓶頸、無法進步，所以報名的張老師的口琴課。在張老師有系統、親切、有耐心的教導下，這幾個月來我的進步很快，也很多。真的非常感謝張老師及社大開這個課程。 ★學員【王琇瑱】 上課心得： 又是一學期和老師學口琴，每次接收的知識都不同；你總是那麼的用心又認真的讓我們聽得懂你要傳達給我們的音樂，下學期一定要再報名!",
