      "id": "story-20",
      "semester": "115-1 春季",
      "source_folder": "1150808 以PO 金工",
      "course": "手作 美學.琺瑯與金工藝術",
      "course_id": "1152A3005",
      "teacher": "簡世杰",
      "title": "手作 美學.琺瑯與金工藝術｜115-1 學員學習心得",
      "excerpt": "手作美學琺瑯工藝 學生林竹君 本學期在簡世杰老師指導下，首次接觸琺瑯金工課程。雖然過去曾學習金工，但琺瑯對我而言是全新的領域，因此老師建議我先從琺瑯色票製作開始，了解不同顏色在燒製後的變化、透明度與呈色效果，為後續創作打下基礎。 學習過程中，我深刻體會到琺瑯是一門需要耐心與細心的工藝。剛開始製作時，常常因動作不夠穩定，不小心碰倒已經填好的琺瑯粉，前面的努力瞬…",
      "full_text": "手作美學琺瑯工藝 學生林竹君 本學期在簡世杰老師指導下，首次接觸琺瑯金工課程。雖然過去曾學習金工，但琺瑯對我而言是全新的領域，因此老師建議我先從琺瑯色票製作開始，了解不同顏色在燒製後的變化、透明度與呈色效果，為後續創作打下基礎。 學習過程中，我深刻體會到琺瑯是一門需要耐心與細心的工藝。剛開始製作時，常常因動作不夠穩定，不小心碰倒已經填好的琺瑯粉，前面的努力瞬間歸零；也曾因不熟悉燒製溫度與時間控制，導致琺瑯粉尚未完全燒結便從金屬表面散落。從琺瑯粉的清洗、填色、乾燥到反覆燒製，每個步驟都需要仔細觀察與調整，而每次開爐看到顏色與光澤產生變化，也讓我感受到琺瑯工藝的獨特魅力。 透過一次次失敗與修正，我逐漸掌握填粉厚薄、燒製火候及材料特性的差異，並完成琺瑯色票、銀杏葉及黑白雙貓等作品。其中銀杏葉以白色琺瑯作為基底，預留空間作為未來色彩疊加的嘗試；黑白雙貓則運用花片與銀箔素材，呈現更豐富的層次與光澤效果，也讓我體會不同媒材結合所帶來的創作可能。 老師雖然初見較為嚴肅，但實際上課後十分親切，經常分享寶貴的創作經驗、材料知識與實務技巧，讓人收穫良多。這是一門兼具技術與創意的課程，推薦給喜歡手作且具自主學習精神的同學參與。",
