      "teacher": "蔡玉雲",
      "title": "傳統國畫山水與創作｜115-1 學員學習心得",
      "excerpt": "1.香燕 學習山水畫，不只是學習如何把景物畫在紙上，更讓我學會放慢腳步，靜下心來觀察大自然。山的高低、樹的疏密、雲霧的遠近，都有它自己的節奏。當心靜下來時，畫畫也成了一種享受，讓忙碌的思緒得到沉澱。 每次拿起畫筆、沾上墨汁，在宣紙上渲染出濃淡層次時，我都覺得這是一場與自己、與大自然的深刻對話。以前生活總是匆忙，看什麼都只是匆匆一瞥；現在學了山水，才發現原來一…",
      "full_text": "1.香燕 學習山水畫，不只是學習如何把景物畫在紙上，更讓我學會放慢腳步，靜下心來觀察大自然。山的高低、樹的疏密、雲霧的遠近，都有它自己的節奏。當心靜下來時，畫畫也成了一種享受，讓忙碌的思緒得到沉澱。 每次拿起畫筆、沾上墨汁，在宣紙上渲染出濃淡層次時，我都覺得這是一場與自己、與大自然的深刻對話。以前生活總是匆忙，看什麼都只是匆匆一瞥；現在學了山水，才發現原來一株樹木的姿態、一片雲霧的流動，甚至是一座山峰的起伏，背後都蘊含著大自然的智慧與律動。在筆墨的運行之間，我學會了包容與放下，不再急著追求畫得有多完美，而是去體會那份運筆時的自在與安詳。 這份專注的過程，就像給心靈澆灌滋養。課堂上和同學們一起討論構圖、分享運筆心得，互相鼓勵與欣賞，更讓這段學習之旅增添了許多溫暖。山水畫帶給我的，早已超越了一幅完成的作品，而是一種生活的態度與心境。讓我在平凡的日常裡，找到一處隨時可以靜心沉澱的小天地，持續享受這份來自筆墨的寧靜與美妙。 安心並快樂地繼續畫下去的最大理由。 2.鄧素娥 52年前我們是同學，52年後我們居然還是同學，這是多麼奇妙又難得的際遇。這次真的託高中同學的福，拉著我一起進入國畫的世界。十八歲時揮毫弄墨，如今七十歲重續筆墨緣，整整放下畫筆52年，今年重新當個國畫新生，與七十歲的自己再度對畫，內心滿是溫馨與奇妙。 課堂上，蔡老師非常溫柔，總是耐心地指導我們每一步。無論是提筆的力道還是墨色的濃淡，老師都溫和地示範與引導，讓人完全沒有壓力，反而充滿了安心感。能遇到這麼溫柔又專業的老師，加上班上溫暖的氛圍，每次上課都覺得心情特別平靜與美好。 活到這個歲數，能和老同學一起並肩學習、重拾年輕時的興趣，真的很幸福。這不只是一堂國畫課，更是我們歲月裡最珍貴的重逢與陪伴。希望未來的日子裡，我們能繼續握緊手中的畫筆，在墨香中慢慢品味屬於我們的七十歲人生。 3.黃美雲 畫畫是我生活中不可或缺的樂趣，以前是，現在也是。四、五年前退休時，為了圓一個年少時未完成的讀書夢，暫時將國畫擱在一旁；四年後的今天，我終於重拾畫筆，繼續我的國畫人生。 我選擇了萬華社大蔡老師的國畫班。老師的畫風傳統雅緻且風格簡約，與我過去所學同出一源。每次上課，老師都會親自示範畫一次，接著大家各自在課堂上練習。這時老師會一個個巡視，不厭其煩地指導我們。最重要的是，老師非常和藹可親，從執筆、運墨到構圖都悉心引導，讓我們在筆墨世界裡重新找到興趣與自信。 此外，我們班就像一個溫暖的大家庭。新同學沒買紙，舊同學二話不說立刻分享；沒有墨，大家先倒一些給你；買到好看的紙，也會特地拿來分送。平時課餘時間，大家還會分享做母親、當阿嬤的各種家庭煩惱與生活趣事。這樣一個充滿溫情的地方，就是我能安心並快樂地繼續畫下去的最大理由。",
